# Strip any older generated gaming block before inserting the current version.
def remove_block(source, element_id):
    marker=f'id="{element_id}"'
    pos=source.find(marker)
    if pos<0:
        return source
    start=source.rfind("<section",0,pos)
    if start<0:
        return source
    token_re=re.compile(r"</?(section|div)\\b[^>]*>",re.I)
    depth=0
    end=None
    for m in token_re.finditer(source,start):
        if m.group(0).lower().startswith("</"):
            depth-=1
            if depth==0:
                end=m.end()
                break
        else:
            depth+=1
    if end is None:
        return source
    return source[:start]+source[end:]

